import re
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

x=y=z=e=0.0
absE=False
obj=None
segs=[]
with open('/app/text.gcode') as f:
    for line in f:
        s=line.strip()
        if s.startswith('M82'): absE=True
        if s.startswith('M83'): absE=False
        if s.startswith('M486'):
            m=re.match(r'M486 S(-?\d+)',s)
            if m: obj=int(m.group(1))
            continue
        if s.startswith('G92'):
            m=re.search(r'E([-\d.]+)',s)
            if m: e=float(m.group(1))
            continue
        if s.startswith('G1') or s.startswith('G0'):
            nx,ny,nz,ne=x,y,z,None
            for tok in s.split():
                if not tok: continue
                if tok[0]=='X': 
                    try: nx=float(tok[1:])
                    except: pass
                elif tok[0]=='Y':
                    try: ny=float(tok[1:])
                    except: pass
                elif tok[0]=='Z':
                    try: nz=float(tok[1:])
                    except: pass
                elif tok[0]=='E':
                    try: ne=float(tok[1:])
                    except: pass
            extr=False
            if ne is not None:
                de=ne-e if absE else ne
                if de>0: extr=True
                if absE: e=ne
            if extr and (nx!=x or ny!=y):
                segs.append((x,y,nx,ny,nz,obj))
            x,y,z=nx,ny,nz

# object 0 = Embossed text
t=[s for s in segs if s[5]==0]
print("text segs",len(t))
zs=sorted(set(s[4] for s in t))
print("text z range",zs[0],zs[-1],len(zs))
fig,ax=plt.subplots(figsize=(20,8))
for x1,y1,x2,y2,zz,o in t:
    ax.plot([x1,x2],[y1,y2],'b-',lw=0.3)
ax.set_aspect('equal')
plt.savefig('/app/text_only.png',dpi=150)
print("saved")
